import json, os
files = sorted(f for f in os.listdir('/tmp/mock_results') if f.endswith('.json'))
for fn in files:
    with open(f'/tmp/mock_results/{fn}') as f:
        data = json.load(f)
    print(f'=== {fn} ===')
    def show_structure(obj, indent=0, max_depth=3):
        if indent >= max_depth:
            print(' ' * indent + '...')
            return
        if isinstance(obj, dict):
            for k, v in obj.items():
                if isinstance(v, (dict, list)):
                    print(' ' * indent + f'{k}: ({type(v).__name__}, len={len(v)})')
                    if isinstance(v, dict) and len(v) <= 6:
                        show_structure(v, indent+2, max_depth)
                    elif isinstance(v, list) and len(v) <= 3:
                        show_structure(v, indent+2, max_depth)
                else:
                    print(' ' * indent + f'{k}: {type(v).__name__} = {repr(v)[:80]}')
        elif isinstance(obj, list):
            for i, item in enumerate(obj[:3]):
                print(' ' * indent + f'[{i}]:')
                show_structure(item, indent+2, max_depth)
            if len(obj) > 3:
                print(' ' * indent + f'... ({len(obj)} items total)')
    show_structure(data)
    print()
"
